	for offset in [-24.0,-6.0,0.0,24.0]:
		_place(bush_ground+Vector2(36,offset));await _pair("bush:"+str(offset))
	for offset in [-24.0,-6.0,0.0,24.0]:
		_place(crop_ground+Vector2(0,offset));await _pair("crop:"+str(offset))
